export const meta = {
  name: 'slice3-design',
  description: 'Plan telelean slice 3 (FROZEN): 2 read-only designers, a synthesizer writing the plan to the scratchpad, then up to 2 critic/fixer rounds',
  phases: [{ title: 'Design' }, { title: 'Synthesize' }, { title: 'Critique' }, { title: 'Fix' }],
}

const R = '/home/zhengyew/telelean'
const S = '/tmp/claude-1000/-home-zhengyew-telelean/20626c17-0334-4498-ad86-9dc24b7010ed/scratchpad'
const SPEC = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/01_spec_v4.md'
const AP = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/02_autopilot_decisions.md'
const P1 = R + '/docs/slice1-plan.md'
const P2 = R + '/docs/slice2-plan.md'
const OUT = S + '/plans/slice3-plan.md'
const U20 = R + '/verbatim_prompt_log/bundle_20/prompt20.md'
const U21 = R + '/verbatim_prompt_log/bundle_21/prompt21_midturn.md'

const SAFETY = `SAFETY AND RESOURCE RULES (mandatory): you are READ-ONLY everywhere except where your task names ONE file you write (${OUT}, in a scratch directory). Never change git state (read-only git such as git diff/log/status is fine). No network, no installs, no Claude CLI, no builds, no tests, no Lean, no tsc/vitest: other agents are building slice 2 in the same working tree right now, so the code is in flux; do not run anything heavy. Never touch ${R}/packages/extension/dist or out. Never send, post, upload or publish anything anywhere. Use reading tools and read-only shell commands only.`

const CONTEXT = `Context: telelean (${R}) is a VS Code extension (TypeScript monorepo: packages/core, runner, extension, webview) that shows a user's beliefs as cards backed by Lean 4 files; Claude formalises and proves through the user's Claude Code CLI with telelean's MCP tools; a non-LLM gate decides what counts. The user's spec is v4.1 (${SPEC}); the build runs on autopilot and every decision taken without the user is logged in ${AP}.

Where the build is:
- Slice 1 (the new board: AXIOMS column + PROPOSITIONS canvas, arrows, glows/bands, pending, follows from nothing, Formalize for dependencies on today's single-target all-or-nothing review, a read-only board during a run) is DONE: ${P1} (sections 1-5 and the section 8 change log) and the code.
- Slice 2 (the review list: real edit sessions with stages, steps, review items, statuses, decline options Reject/Shaky, Submit review, Apply with the backstop, the session Undo stack) is being BUILT right now by other agents, sub-slice by sub-slice, following ${P2}. That plan is final: its section 2 and 2.9 contracts are the interface slice 3 builds on; its section 7.2 holds its decisions D2-1..D2-74; its section 8 change log records what each builder decided (read the latest entries). AP-24 in ${AP} explains how slice 2 was simplified (one reveal per stage; no decisions while a Claude step runs; a Formalize queue runs to its end before its stage opens).

SLICE 3 = FROZEN (item 3 of the spec's slice order, ★D8 (a)). It covers:
1. Spec section 5, FZ-1..FZ-13, in full: freezing cards, fields, arrows, "follows from nothing" marks and a proposition's Dependencies; keep-empty freezes (FZ-2); the mechanical check with frozen values at every judged state, text compared directly and meaning compared in Lean (FZ-3); held content = what frozen Lean relies on after elaboration (FZ-4), with the chain mark; unfreeze requests that pause the step (FZ-5), with Select them / Continue / Keep frozen / Allow this change and the "meaning changed by X" items; only the user unfreezes (FZ-6); reasons (FZ-7); restoring standing freezes when a session ends, with keep ticks (FZ-8, EN-2); availability everywhere, at any time (FZ-9); freezing while Claude works (FZ-10); the look (FZ-11, theme colour telelean.frozen, lock badges, chips, high contrast, the session banner); the rename of "statements frozen" to "statements fixed" (FZ-12); arrows and dependencies (FZ-13).
2. Everything the slice-2 plan defers to slice 3 (grep ${P2} for "slice 3"): Accept freezes (RV-4); keep ticks in the end confirmation; "Open the whole model" and "Claude may add cards" in Formalize's ▾ (D2-12; the user's D3 answer); Claude creating cards (card:<node> add items); Delete items; Change items for existing declarations; Proof broken items; Remove arrow items; the "meaning changed" item of an axiom; frozen and held content in the per-step checks and in Apply's backstop (spec Appendix B); and the hooks the slice-2 plan leaves (e.g. its section 4.10 "Slice 3 hook").
3. NOT in slice 3: the transform window (slice 4: the freeze reason "you filled it in a transform", TR-15, the "Transform cards…" session start and its banner — leave clean hooks only) and references (slice 5: FZ-4's #-reference holding — hook only).

The user's own words (read them; they outrank any simplification): ${U20} lines 26-59 (FROZEN 1-5, REVIEW 3, 5, 7, 8, INITIATING EDIT SESSIONS 2), and in ${U21} mid-turn message 1, D3: "everything outside the cards touched by the selected dotted arrows is frozen. However, there should be an easy way to make the entire model unfrozen ...". Note especially: "Claude can *never* edit a frozen card under any circumstances. If claude wants to edit a frozen field, it MUST ask the user to unfreeze it *first*, and the user must manually unfreeze it ... Then Claude can edit it not because the user has 'given approval', but specifically and mechanically because the card itself is no longer frozen"; "The only time frozen status can be removed automatically is if a card was frozen during an EDIT SESSION and that same session has ended"; and "At ALL times (at all stages in all interfaces) where a card or its fields are visible, a user should be able to ... click a 'freeze' or 'unfreeze' option ... at any time" (also "freeze all other cards" / "unfreeze all other cards").

SIMPLICITY DIRECTIVE: slice 2's plan had to be simplified (AP-24) because its most intricate mechanisms kept failing adversarial review. Design slice 3 for the simplest SOUND mechanism from the start: prefer coarse, whole-state, mechanical checks (compare the judged state against stored frozen values) over incremental bookkeeping; prefer refusing a state over repairing it; reuse slice-2 mechanisms (judgeState, the reducer, the session stack, the base mask, the end confirmation) instead of parallel ones. But do NOT narrow what the user explicitly asked for (freezing at ALL times including while Claude works, keep-empty, ask-first, the restore at session end) unless there is no sound simple way; any narrowing is an AUTOPILOT DECISION with the alternative and how to reverse it.

Constraints: tests never call real Claude (FakeBackend / recorded streams); the user's installed extension runs from packages/extension/dist (never built except at verified slice ends); tests run single-worker under memory caps; the user reviews the design later, so every choice is logged.`

const DESIGN_SCHEMA = {
  type: 'object',
  properties: {
    summary: { type: 'string' },
    current_state: { type: 'string', description: 'what exists today and in the slice-2 plan in your area, with file:line or plan-section references' },
    design: { type: 'string', description: 'the proposed design in detail: data model, contracts (TypeScript types), algorithms, protocol messages, state machine, persistence' },
    sub_slices: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, scope: { type: 'string' }, files: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' }, risk: { type: 'string' } }, required: ['id', 'scope', 'files', 'tests'] } },
    open_questions: { type: 'array', items: { type: 'string', description: 'a decision needed, with your recommended answer and the alternative' } },
    safety_notes: { type: 'array', items: { type: 'string' } },
  },
  required: ['summary', 'current_state', 'design', 'sub_slices', 'open_questions', 'safety_notes'],
}

phase('Design')
const lenses = [
  { key: 'engine-checks', text: `YOUR AREA: THE FREEZE ENGINE AND THE CHECKS (core + runner). Design: (1) the freeze store — where telelean keeps freezes so Claude can neither see nor change them (outside the run's ws/ sandbox; consider the model folder's telelean state vs the run directory vs workspace storage, and how standing freezes survive reload, VS Code restarts, History restores and Undo), its versioned format, what a freeze addresses (card id, field, arrow (source,target), a follows-from-nothing mark, Dependencies), reasons (FZ-7) and frozen values (FZ-3, including the per-step limits of ES-2 and the session's starting freeze from Formalize, with "Open the whole model" and "Claude may add cards"); (2) the check at every judged state: a new gate rule (or rules) in core's judgeState (slice-2 plan section 4.9) comparing frozen text exactly and frozen meaning in Lean (how: elaborated facts — valueConsts from 1d, typeConsts from 2b3 — and the held closure of FZ-4: what frozen Lean relies on after elaboration, a .holds held by its type only), with refusal messages for Claude, and how a check failing only because of a freeze made during the step does not count as an attempt (FZ-10); (3) unfreeze requests (FZ-5): a new MCP tool, the step pausing like today's questions (read runner/src/run/manager.ts around pendingAsk/waiting-for-answer and the slice-2 plan's section 2.8 tools and turns), Continue / Keep frozen answers telling Claude exactly what is unfrozen, Allow this change on held content with the "meaning changed by X" items and their ordering/decline rules; (4) RV-4 (Accept freezes the accepted content as a session reason) and FZ-7's interplay with slice 2's reducer and statuses (Unfreeze returns an accepted item covering the field to "in review"); (5) FZ-8: restoring standing freezes at session end (Apply, Exit, failure) with keep ticks, and what Undo/History do to freezes; (6) the slice-2 deferrals: Claude creating cards, Delete items, Change items for existing declarations, Proof broken, Remove arrow items, the "meaning changed" item of an axiom — whatever slice 3 must build so that the whole model can be opened safely; and Apply's backstop (Appendix B) with frozen and held content; (7) the test strategy: FakeBackend cheat scenarios (Claude edits a frozen field; fills a keep-empty field; removes a frozen arrow or a frozen follows-from-nothing mark; adds an arrow into frozen Dependencies; changes a held definition or a held card's statement; inserts an instance, attribute or open that changes frozen meaning; deletes a card with a frozen field; edits frozen content and restores it before the check; races a freeze made mid-step) and unit tests. Read: core/src/gate/*, core/src/review/* (slice 2, in flux), core/src/run.ts, core/src/model.ts, core/src/project/*, runner/src/run/manager.ts, runner/src/gate/*, runner/src/proposal/*, runner/src/semantic/*, the spec sections 5, 7, 9, 11, 12, 14 and Appendix A/B, and the slice-2 plan sections 2, 3, 4.` },
  { key: 'ui-protocol', text: `YOUR AREA: THE FREEZE UI, PROTOCOL AND UNDO (webview + extension host + protocol). Design: (1) the Context Menu actions Freeze / Unfreeze / Freeze all other cards / Unfreeze all other cards (with its confirmation, the count of standing freezes it removes, and "also un-accept"), their enablement and disabled reasons, how cards, fields, arrows, follows-from-nothing marks and a proposition's Dependencies are selected (read the slice-1 board code: packages/webview/src/board/*, board/canvas/*, header/ContextSection.tsx, contextActions.ts, menu.ts, ContextMenu.tsx, state/store.ts) and everywhere FZ-9 requires them (the Current view outside a session, the Proposed view, review items, the end confirmation, request cards — the slice-2 plan's section 5 describes the review UI being built now; the transform window comes in slice 4), at any time including while Claude works (FZ-9, FZ-10 dialogs: which version to freeze for a card with an item in review, unfreeze-on-reject, confirming a keep-empty freeze of a field Claude is filling); (2) the look (FZ-11): the aura in a theme colour telelean.frozen contributed in the extension's package.json and drawn inside the card so it combines with slice 1's blue/green glows and the diff halos, lock badges on cards, fields, arrows (at the middle) and where arrows enter frozen Dependencies, the "dependencies frozen" chip, high-contrast replacements, the legend entry, the session banner per start mode (and the board marking what Claude may change instead of an aura on every card), the chain mark "held by ‹card›"; (3) request cards (FZ-5) in the review panel with Select them, Continue, Keep frozen and Allow this change; (4) the end confirmation's list of freeze changes and keep ticks (FZ-8, EN-2) and Formalize's ▾ with "Open the whole model" and "Claude may add cards" (D3, D2-12); (5) the rename of "statements frozen" to "statements fixed" with its own icon (FZ-12); (6) Undo: freeze changes go on the Undo stack of the view they are made in (FZ-9 last bullet: the board's Undo outside a session, the session stack inside — read the slice-2 plan's section 5.12 and the spec section 12 UN-1..UN-7), never touch a file and make no History snapshot, and can never interfere between the Current and Proposed stacks (the user insisted on this); (7) protocol messages host<->webview with validators (core/src/protocol.ts style), store state, and tests (webview unit tests, extension unit tests, Playwright specs against the mock host harness: packages/webview/test/e2e/* and test/harness/*).` },
]
const designs = await parallel(lenses.map((l) => () => agent(`${SAFETY}\n\n${CONTEXT}\n\n${l.text}\n\nBe concrete: name files, functions, types and messages; give TypeScript type sketches for new contracts; reuse what exists and what slice 2 is building. Propose sub-slices for your area (each buildable and testable on its own by one agent, in dependency order). List open questions with your recommended answer and the alternative (the integrator decides on autopilot). Note every safety property your design must preserve and how it is tested.`, { label: `design:${l.key}`, phase: 'Design', schema: DESIGN_SCHEMA })))
log(`designs: ${designs.filter(Boolean).length}/2`)

phase('Synthesize')
const plan = await agent(`${SAFETY} EXCEPTION: you write exactly ONE new file, ${OUT} (create it; nothing else anywhere).\n\n${CONTEXT}\n\nTwo designers each produced a design for one area of slice 3 (JSON below). Write the slice-3 implementation plan as ${OUT}, in the style and structure of ${P2} (read its sections 0, 1, 2 and 7 first to copy the conventions), but leaner — aim for at most about 1,200 lines. Sections: 0 rules for everyone (as slice 2's section 0); 1 order of work (at most 7 sub-slices named 3a, 3b, ...; each small enough for one builder agent, each ending with every package compiling and unit tests passing; say what each contains and which spec clauses it implements); 2 contracts decided precisely (types, persistence formats, protocol messages with validators, MCP tool, gate rules and their messages for Claude), written against the slice-2 contracts; 3 the freeze engine and checks; 4 the UI; 5 Undo and persistence; 6 tests per sub-slice, including FakeBackend cheat scenarios; 7 decisions (D3-1, D3-2, ... each marked "AUTOPILOT DECISION:" with its alternative and how to reverse it); 8 change log (empty, for builders). Resolve every conflict between the designs explicitly and decide every open question (minimal, sound, consistent with the user's words). Keep the spec's clause IDs as references. After writing the file, return a short summary: the sub-slice list (id + one line), the decisions (one line each), and anything you could not resolve.\n\n=== DESIGNS ===\n${JSON.stringify(designs.filter(Boolean), null, 1)}`, { label: 'synthesize:plan', phase: 'Synthesize' })

const CRIT = { type: 'object', properties: { summary: { type: 'string' }, findings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] }, lens: { type: 'string', enum: ['soundness', 'implementability', 'simplicity', 'user-intent'] }, where: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['id', 'severity', 'lens', 'where', 'problem', 'fix'] } } }, required: ['summary', 'findings'] }
const DISP = { type: 'object', properties: { summary: { type: 'string' }, dispositions: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, action: { type: 'string', enum: ['fixed', 'rejected', 'partly'] }, note: { type: 'string' } }, required: ['id', 'action', 'note'] } } }, required: ['summary', 'dispositions'] }

const rounds = []
for (let round = 1; round <= 2; round++) {
  phase('Critique')
  const prior = rounds.length ? `\n\nAn earlier round already raised findings and a fixer handled them (dispositions below). Check that each "fixed" one really is fixed and each "rejected" one is rightly rejected (re-raise it if not), then look for NEW problems — especially ones the fixes introduced.\n=== EARLIER ROUNDS ===\n${JSON.stringify(rounds.map((r) => ({ round: r.round, findings: r.crit.findings, dispositions: r.fix ? r.fix.dispositions : null })), null, 1)}` : ''
  const crit = await agent(`${SAFETY}\n\n${CONTEXT}\n\nCritique the slice-3 plan at ${OUT}, adversarially, on four lenses: (1) SOUNDNESS — could Claude change frozen or held content (text or meaning) and have it count; fill a keep-empty field; remove a frozen arrow or mark; could a freeze be lost or wrongly kept on rollback, Cancel, Retry, reload, crash, Undo/Redo, History restore or session end (FZ-8); could a request or "Allow this change" let Claude change something without the user's own Unfreeze or individual acceptance; could a freeze made while Claude works race with the judge; could the Current and Proposed Undo stacks interfere? (2) IMPLEMENTABILITY — are the contracts complete and consistent with the slice-2 plan's contracts (${P2} sections 2 and 2.9) and the slice-1 code (read it); is each sub-slice buildable by one agent, in order, with tests? (3) SIMPLICITY — flag any mechanism more intricate than needed and give a simpler sound one (slice 2 had to be simplified late; avoid that). (4) USER-INTENT — does it do what the user's own words require (${U20} lines 26-59; D3 in ${U21}), and is every narrowing logged as an AUTOPILOT DECISION? Report findings with concrete fixes to the plan text. Do not report style nits unless they cause ambiguity.${prior}`, { label: `critique:r${round}`, phase: 'Critique', schema: CRIT })
  if (!crit) { log(`round ${round}: critic returned nothing`); break }
  const must = crit.findings.filter((f) => f.severity === 'blocker' || f.severity === 'major')
  log(`round ${round}: ${crit.findings.length} findings, ${must.length} blocker/major`)
  if (crit.findings.length === 0) { rounds.push({ round, crit, fix: null }); break }
  phase('Fix')
  const fix = await agent(`${SAFETY} EXCEPTION: you edit exactly ONE file, ${OUT} (nothing else anywhere).\n\n${CONTEXT}\n\nYou are the FIXER of the slice-3 plan at ${OUT}. A critic raised the findings below. Fix every blocker and major finding in the plan text, and minor ones when cheap and clearly right; if you judge a finding wrong, do not change the plan for it and say why. Keep the plan coherent: when you change a contract, update every section that uses it (sub-slice scopes, tests, decisions). New or changed decisions go in section 7 as "AUTOPILOT DECISION:" with the alternative and the reversal. Add a dated line per round to section 8 ("review round ${round}: …"). Return one disposition per finding.\n\n=== FINDINGS ===\n${JSON.stringify(crit.findings, null, 1)}`, { label: `fix:r${round}`, phase: 'Fix', schema: DISP })
  rounds.push({ round, crit, fix })
  if (must.length === 0) break
}
return { designs, plan, rounds }
